def split_row(line: str):
    """Split one CSV line into fields without splitting quoted commas."""
    fields = []
    field = []
    in_quotes = False
    i = 0

    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                # Two quotes in a quoted field stand for one quote.
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
        elif char == '"' and not field:
            in_quotes = True
        elif char == ',':
            fields.append(''.join(field))
            field = []
        else:
            field.append(char)
        i += 1

    fields.append(''.join(field))
    return fields

